// On-demand crawler API — turns an incoming HTTP request into a ScraperAPI
// crawler job. POST a JSON body to the "Receive crawl request" webhook:
//
//   {
//     "startUrl": "https://example.com/blog",        // required
//     "includeRegexp": "https://example\\.com/blog.*", // optional
//     "maxDepth": 1,                                   // optional
//     "countryCode": "us",                            // optional
//     "render": false                                  // optional
//   }
//
// The crawler API requires either a max depth or a crawl budget, so this
// node always sends one. It defaults maxDepth to 1 (start URL + one level
// of links) — the cheapest option and the only depth allowed on the Free
// plan; depth > 1 needs a paid ScraperAPI plan.
//
// IMPORTANT: paste the "Receive crawl results" webhook Production URL into
// CALLBACK_URL below before going live — that is where ScraperAPI streams
// each crawled page.

const CALLBACK_URL = 'https://YOUR-N8N-HOST/webhook/crawl-results';

const body = $json.body || {};
const startUrl = body.startUrl;
if (!startUrl) {
  throw new Error('Request body must include "startUrl".');
}

// Default the include filter to "anything under the start URL" so a bare
// { "startUrl": ... } request stays scoped instead of crawling the whole
// domain. Override by passing your own includeRegexp.
const escaped = startUrl.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

return [{
  json: {
    startUrl,
    includeRegexp: body.includeRegexp || (escaped + '.*'),
    maxDepth: body.maxDepth != null ? Number(body.maxDepth) : 1,
    countryCode: body.countryCode || 'us',
    render: body.render === true,
    callbackUrl: CALLBACK_URL,
  },
  pairedItem: { item: 0 },
}];

// ScraperAPI streams one POST per crawled page to this webhook, plus a
// final job-summary POST when the crawl finishes. Keep only successful
// per-page results; drop the summary and any failed fetches.

const payload = $json.body || $json;
const results = Array.isArray(payload) ? payload : [payload];

const out = [];
for (const r of results) {
  const resp = r && r.response;
  const status = resp && resp.statusCode;
  // A page result has a url and a response.body string; the job summary
  // (jobState / finished counters) and failed fetches are skipped.
  if (!r || !r.url || !resp || typeof resp.body !== 'string') continue;
  if (status && status >= 400) continue;
  out.push({
    json: {
      url: r.url,
      content: resp.body,
      status_code: status || 200,
      scraped_at: new Date().toISOString(),
    },
    pairedItem: { item: 0 },
  });
}

return out;
